const trackVol = (n) => (n === "bgm_menu" ? 55 : 45);
const playTrack = (n) => {
  try {
    if (F.music) { if (sm.playMusicOnChannel) sm.playMusicOnChannel(n, 0, true, trackVol(n), 1); else sm.playMusic(n, true, trackVol(n), 1); }
    gTrack.setString(n);
  } catch (e) {}
};
