    if (cmd === "pop") scene.requestChange(C.POP_SCENE);
    else if (cmd === "push") scene.requestChange(C.PUSH_SCENE, name);
    else scene.requestChange(C.CLEAR_SCENES, name);
  } catch (e) {
    const stack = game.getSceneStack();
    if (cmd === "pop") stack.pop(); else if (cmd === "push") stack.push(name); else stack.replace(name, true);
  }
