const click = md && !S.pm;
S.pm = md;
const edge = (k) => { const d = isDown(k); const w = S.prev[k]; S.prev[k] = d; return d && !w; };
const rep = (k) => {   // tekan = 1x, tahan = berulang
  const d = isDown(k); const was = S.prev[k]; S.prev[k] = d;
