  if (!was) { S.hold[k] = S.T + 0.35; return true; }
  if (S.T >= S.hold[k]) { S.hold[k] = S.T + 0.06; return true; }
  return false;
};
const hitBtn = (o) => mx >= o.getX() + 10 && mx <= o.getX() + o.getWidth() - 10 && my >= o.getY() + 8 && my <= o.getY() + o.getHeight() - 9;
const go = (fn) => { if (!S.leave) S.leave = { t: 0, fn: fn, done: false }; };
