  if (color && o.setColor) o.setColor(color);
  if (size && o.setCharacterSize) o.setCharacterSize(size);
};
const ctext = (o, str, cx, color, size) => { if (!o) return; setTxt(o, str, color, size); o.setX(cx - o.getWidth() / 2); };
const mmss = (s) => { const t = Math.max(0, Math.round(s)); return Math.floor(t / 60) + ":" + (t % 60 < 10 ? "0" : "") + (t % 60); };
if (edge("mute")) { const gm = gv("muted"); const m = gm.getAsNumber() === 1 ? 0 : 1; gm.setNumber(m); applyVol(); }
if (S.msgT > 0) { S.msgT -= dt; if (S.msgT <= 0) S.msg = ""; }
S.conf = Math.max(0, S.conf - dt);
const firstFrame = !S.init;
if (edge("toko") && !S.leave) { sfx("klik_sound", 70); F.tokoFrom = "menu"; go(() => nav("clear", "Toko")); }
if (firstFrame) {
  for (const n of ["MenuBg", "MenuLogo", "BtnMulai", "BtnLevel", "BtnCara", "BtnSetting", "BtnTentang", "Coin", "GateAND", "GateOR", "GateNOT", "Resistor", "Kapasitor", "LedBlink", "TxtStat"]) for (const o of obs(n)) o.setX(o.getX() + S.dx);
  const bg = ob("MenuBg");
  if (bg && W > 1600) { bg.setX(0); bg.setWidth(W); }
  const tr = ob("Tirai");
  if (tr) { tr.setWidth(W + 40); tr.setHeight(720); tr.setPosition(-20, -20); }
}
const hintO = ob("TxtHint"), footO = ob("TxtFooter");
