const listNav = (items) => {
  let hov = -1;
  items.forEach((it, i) => { if (it.o && hitBtn(it.o)) hov = i; });
  if (moved && hov >= 0) S.sel = hov;
  const n = items.length;
  if (edge("up")) S.sel = (S.sel + n - 1) % n;
  if (edge("down")) S.sel = (S.sel + 1) % n;
  if (S.sel !== S.lastSel) { if (S.lastSel !== undefined) sfx("klik_sound", 40); S.lastSel = S.sel; }
  let act = -1;
  if (click && hov >= 0) { S.sel = hov; act = hov; }
  else if (edge("ok")) act = S.sel;
  items.forEach((it, i) => { if (it.o) it.o.setAnimationName((it.n || "n") === "n" ? (i === S.sel ? "h" : "n") : (i === S.sel ? it.n + "h" : it.n)); });
  return act;
};

// ===== MENU UTAMA =====
const items = [
  { o: ob("BtnMulai"), k: "mulai" }, { o: ob("BtnLevel"), k: "level" }, { o: ob("BtnCara"), k: "cara" },
  { o: ob("BtnSetting"), k: "setting" }, { o: ob("BtnTentang"), k: "tentang" }
].filter((it) => it.o);
if (firstFrame) {
