  if (k === "mulai") { sfx("start_sound", 70); gv("deaths").setNumber(0); gv("started").setNumber(0); go(() => nav("clear", "Level1")); }
  else if (k === "level") { sfx("switch_sound", 70); go(() => nav("clear", "PilihLevel")); }
  else if (k === "cara") { sfx("switch_sound", 70); go(() => nav("clear", "CaraMain")); }
  else if (k === "setting") { sfx("switch_sound", 70); F.from = "menu"; go(() => nav("clear", "Pengaturan")); }
  else if (k === "tentang") { sfx("switch_sound", 70); go(() => nav("clear", "Tentang")); }
}
// Animasi latar: logo melayang, bit 0/1 naik, Sheren berlari mengambil koin, komponen bergoyang pelan.
const logo = ob("MenuLogo");
