  for (const o of obs(n)) { if (o._y0 === undefined) o._y0 = o.getY(); o.setY(o._y0 + 4 * Math.sin(S.T * 1.3 + o.getX() * 0.01)); }
}
const nDone = [1, 2, 3].filter((k) => F.done[k] === true).length;
setTxt(ob("TxtStat"), "Level selesai: " + nDone + " / 3      Skor kuis terbaik: " + (F.quiz >= 0 ? F.quiz + " / 6" : "-"), "130;230;255", 16);
ctext(hintO, "Klik tombol, atau pakai  W / S  +  ENTER      T = Toko", W / 2, "255;224;60", 15);
ctext(footO, "Sheren Agnesia Sukarno   -   dibuat dengan GDevelop 5   -   v1.0", W / 2, "150;190;220", 14);

// ---- Efek fade masuk/keluar.
const tirai = ob("Tirai");
if (tirai) {
  if (tirai.setOpacity) {
    if (S.leave) {
      S.leave.t += dt;
      const p = Math.min(1, S.leave.t / 0.22);
      tirai.setOpacity(255 * p);
      if (p >= 1 && !S.leave.done) { S.leave.done = true; S.leave.fn(); }
    } else {
