  for (const n of ["MenuBg", "JudulJeda", "PanelJeda", "BtnLanjut", "BtnUlang", "BtnSetting", "BtnMenu"]) for (const o of obs(n)) o.setX(o.getX() + S.dx);
  const bg = ob("MenuBg");
  if (bg && W > 1600) { bg.setX(0); bg.setWidth(W); }
  const tr = ob("Tirai");
  if (tr) { tr.setWidth(W + 40); tr.setHeight(720); tr.setPosition(-20, -20); }
}
const hintO = ob("TxtHint"), footO = ob("TxtFooter");
// Daftar tombol vertikal: pilih dengan panah atas/bawah (atau W/S) + ENTER, atau arahkan & klik mouse.
const listNav = (items) => {
  let hov = -1;
  items.forEach((it, i) => { if (it.o && hitBtn(it.o)) hov = i; });
  if (moved && hov >= 0) S.sel = hov;
  const n = items.length;
  if (edge("up")) S.sel = (S.sel + n - 1) % n;
  if (edge("down")) S.sel = (S.sel + 1) % n;
  if (S.sel !== S.lastSel) { if (S.lastSel !== undefined) sfx("klik_sound", 40); S.lastSel = S.sel; }
  let act = -1;
  if (click && hov >= 0) { S.sel = hov; act = hov; }
  else if (edge("ok")) act = S.sel;
  items.forEach((it, i) => { if (it.o) it.o.setAnimationName((it.n || "n") === "n" ? (i === S.sel ? "h" : "n") : (i === S.sel ? it.n + "h" : it.n)); });
  return act;
};

// ===== JEDA (ditumpuk di atas level) =====
const items = [
  { o: ob("BtnLanjut"), k: "lanjut" }, { o: ob("BtnUlang"), k: "ulang" }, { o: ob("BtnSetting"), k: "setting" }, { o: ob("BtnMenu"), k: "menu" }
].filter((it) => it.o);
const lvl = gv("curLevel").getAsString() || "Level1";
const act = listNav(items);
const resume = () => { sfx("klik_sound", 70); nav("pop"); };
if (!S.leave) {
  if (edge("esc") || edge("p")) resume();
  else if (act >= 0) {
    const k = items[act].k;
    if (k === "lanjut") resume();
    else if (k === "ulang") { sfx("start_sound", 70); go(() => nav("clear", lvl)); }
    else if (k === "setting") { sfx("switch_sound", 70); F.from = "pause"; nav("push", "Pengaturan"); }
    else if (k === "menu") { sfx("klik_sound", 70); go(() => nav("clear", "MenuUtama")); }
  }
}
const nm = { Level1: "Level 1: SR Latch", Level2: "Level 2: D Flip-Flop", Level3: "Level 3: JK Flip-Flop", Kuis: "Kuis Akhir" }[lvl] || lvl;
ctext(ob("TxtInfo"), nm + "   -   Percobaan: " + (gv("deaths").getAsNumber() + 1), W / 2, "130;230;255", 18);
ctext(hintO, "ESC atau P = lanjutkan      T = Toko", W / 2, "255;224;60", 15);
ctext(footO, "'Ulang level' mengulang dari awal level ini.  M = suara on/off", W / 2, "150;190;220", 14);

// ---- Efek fade masuk/keluar.
const tirai = ob("Tirai");
if (tirai) {
  if (tirai.setOpacity) {
    if (S.leave) {
      S.leave.t += dt;
      const p = Math.min(1, S.leave.t / 0.22);
      tirai.setOpacity(255 * p);
      if (p >= 1 && !S.leave.done) { S.leave.done = true; S.leave.fn(); }
    } else {
      S.fade = Math.min(1, S.fade + dt / 0.35);
      tirai.setOpacity(255 * (1 - S.fade));
    }
  } else if (tirai.hide) {
    tirai.hide(true);
    if (S.leave && !S.leave.done) { S.leave.done = true; S.leave.fn(); }
  }
}
S.init = true;
} catch (e) {
  console.error("FlipFlop Circuit Quest - menu error:", e);
}

// ===== MENU HOOK (awal): pengaturan suara, tombol ESC / P = menu jeda, penghitung waktu level =====
try {
const scene = runtimeScene;
const game = scene.getGame();
const sm = game.getSoundManager();
const input = game.getInputManager();
const KEY = "ffcq_sheren_v1";
if (!game._ffcq) {
  const def = { vol: 80, music: 1, sfx: 1, unlockAll: 0, done: {}, best: {}, quiz: -1, from: "menu" };
  let st = def;
  try { const raw = window.localStorage.getItem(KEY); if (raw) st = Object.assign({}, def, JSON.parse(raw)); } catch (e) { st = def; }
  if (!st.done || typeof st.done !== "object") st.done = {};
  if (!st.best || typeof st.best !== "object") st.best = {};
  st.from = "menu";
  game._ffcq = st;
}
const gv = (n) => game.getVariables().get(n);
if (!sm._ffcqPatched) {
  sm._ffcqPatched = true;
  const oPlay = sm.playSound.bind(sm);
  sm.playSound = function (n, l, v, p) { if (!game._ffcq.sfx) return undefined; return oPlay(n, l, v, p); };
  const oVol = sm.setGlobalVolume.bind(sm);
  sm.setGlobalVolume = function (v) { return oVol(Math.max(0, Math.min(100, v * game._ffcq.vol / 100))); };
  if (sm.playMusicOnChannel) {
    const oM = sm.playMusicOnChannel.bind(sm);
    sm.playMusicOnChannel = function (n, c, l, v, p) { if (!game._ffcq.music) return undefined; return oM(n, c, l, v, p); };
  }
  if (sm.playMusic) {
    const oM2 = sm.playMusic.bind(sm);
    sm.playMusic = function (n, l, v, p) { if (!game._ffcq.music) return undefined; return oM2(n, l, v, p); };
  }
  sm.setGlobalVolume(gv("muted").getAsNumber() === 1 ? 0 : 100);
}
gv("curLevel").setString("Level1");
const nowMs = Date.now();
const dt = Math.min(0.1, (nowMs - (scene._lt0 || nowMs)) / 1000);
scene._lt0 = nowMs;
scene._lt = (scene._lt || 0) + dt;   // detik bermain (tidak bertambah saat dijeda)
const down = input.isKeyPressed(27) || input.isKeyPressed(80);
if (scene._escWas === undefined) scene._escWas = down;   // tombol yang masih ditahan saat level mulai tidak dihitung
if (down && !scene._escWas) {
  scene._escWas = true;
  try { sm.playSound("klik_sound", false, 70, 1); } catch (e) {}
  try { scene.requestChange(gdjs.SceneChangeCommand.PUSH_SCENE, "Jeda"); } catch (e) { game.getSceneStack().push("Jeda"); }
} else scene._escWas = down;
} catch (e) {
  console.error("FlipFlop Circuit Quest - menu hook error:", e);
}

// ===== ATRIBUT, ITEM & BOOSTER (JavaScript Event): nyawa, energi, bit, XP, kapasitor, resistor, LED, Game Over =====
try {
  const scene = runtimeScene;
  const game = scene.getGame();
  const input = game.getInputManager();
  const sm = game.getSoundManager();
  const F = game._ffcq;
  const LV = 1;
  if (F) {
    const DEFA = { bit: 0, xp: 0, lives: 3, energy: 100, kap: 0, res: 0, got: {}, run: false, lastLevel: "Level1", lastQuiz: -1, tokoFrom: "menu" };
    for (const k in DEFA) if (F[k] === undefined) F[k] = DEFA[k];
    const save = () => { try { window.localStorage.setItem("ffcq_sheren_v1", JSON.stringify(F)); } catch (e) {} };
    const V = (n) => scene.getVariables().get(n).getAsNumber();
    const SV = (n, v) => scene.getVariables().get(n).setNumber(v);
    const plv = () => Math.min(5, 1 + Math.floor(F.xp / 100));
    const maxE = () => 100 + 10 * (plv() - 1);
    const sfx = (n, v) => { try { sm.playSound(n, false, v === undefined ? 100 : v, 1); } catch (e) {} };
    const now = Date.now();
    const dtm = Math.min(0.1, (now - (scene._at0 || now)) / 1000);
    scene._at0 = now;
    const toast = (s) => { scene._msg = s; scene._msgT = 2.5; };
    const player = scene.getObjects("Player")[0];
    const b = player ? player.getBehavior("PlatformerObject") : null;
    const keyOf = { ItemKap: "k", ItemRes: "r", ItemLed: "l" };

    // --- Awal level (sekali)
    if (!scene._atInit) {
      scene._atInit = true;
      if (!F.run) { F.run = true; F.lives = 3; F.energy = maxE(); F.got = {}; }
      F.lastLevel = "Level" + LV;
      for (const nm in keyOf) for (const o of scene.getObjects(nm).slice()) if (F.got["L" + LV + keyOf[nm]]) o.deleteFromScene(scene);
      scene._turbo = 0; scene._shield = 0; scene._inv = 0; scene._qw = false; scene._ew = false; scene._pdead = false; scene._go = false; scene._goSent = false; scene._rew = false;
      scene._msg = ""; scene._msgT = 0;
      save();
    }
    scene._msgT = Math.max(0, (scene._msgT || 0) - dtm);
    if (scene._inv > 0) scene._inv -= dtm;
    let dead = V("dead") === 1;
    const fin = V("finished") === 1;

    // --- Mengambil item
    if (player && !dead && !fin) {
      const px = player.getX(), py = player.getY(), pw = player.getWidth(), ph = player.getHeight();
      const hit = (o) => px < o.getX() + o.getWidth() && px + pw > o.getX() && py < o.getY() + o.getHeight() && py + ph > o.getY();
      for (const o of scene.getObjects("ItemKap").slice()) if (hit(o)) { o.deleteFromScene(scene); F.kap++; F.energy = Math.min(maxE(), F.energy + 30); F.got["L" + LV + "k"] = true; sfx("coin_sound"); toast("Kapasitor +1 (energi +30). Tekan Q = Turbo"); save(); }
      for (const o of scene.getObjects("ItemRes").slice()) if (hit(o)) { o.deleteFromScene(scene); F.res++; F.got["L" + LV + "r"] = true; sfx("coin_sound"); toast("Resistor +1. Tekan E = Perisai"); save(); }
      for (const o of scene.getObjects("ItemLed").slice()) if (hit(o)) {
        o.deleteFromScene(scene); F.got["L" + LV + "l"] = true;
        if (F.lives < 5) { F.lives++; toast("LED: nyawa +1"); } else { F.bit += 5; toast("LED: nyawa penuh, bit +5"); }
        sfx("benar_sound", 90); save();
      }
    }

    // --- Booster: Q = Turbo, E = Perisai
    const qd = input.isKeyPressed(81), ed = input.isKeyPressed(69);
    if (qd && !scene._qw && !dead && !fin) {
      if (scene._turbo > 0) toast("Turbo masih aktif");
      else if (F.kap < 1) toast("Tidak punya Kapasitor (beli di Toko, tekan T di menu)");
      else if (F.energy < 40) toast("Energi kurang (butuh 40)");
      else { F.kap--; F.energy -= 40; scene._turbo = 8; sfx("switch_sound"); toast("TURBO aktif 8 detik!"); save(); }
    }
    scene._qw = qd;
    if (ed && !scene._ew && !dead && !fin) {
      if (scene._shield) toast("Perisai sudah aktif");
      else if (F.res < 1) toast("Tidak punya Resistor (beli di Toko)");
      else { F.res--; scene._shield = 1; sfx("switch_sound"); toast("PERISAI aktif: menahan 1 sengatan listrik"); save(); }
    }
    scene._ew = ed;

    // --- Efek Turbo + energi pulih
    if (b) {
      const on = scene._turbo > 0;
      if (on !== scene._turboOn) { scene._turboOn = on; try { b.setJumpSpeed(on ? 693 : 620); b.setMaxSpeed(on ? 336 : 280); } catch (e) {} }
    }
    if (scene._turbo > 0) scene._turbo = Math.max(0, scene._turbo - dtm);
    else F.energy = Math.min(maxE(), F.energy + 5 * dtm);

    // --- Kematian baru: perisai menahan, atau nyawa berkurang (jurang tidak bisa ditahan)
    if (dead && !scene._pdead) {
      const pit = player ? player.getY() > 540 : false;
      if (!pit && (scene._inv > 0 || scene._shield)) {
        SV("dead", 0); SV("deathTime", 0);
        try { player.activateBehavior("PlatformerObject", true); } catch (e) {}
        const gd = game.getVariables().get("deaths");
        gd.setNumber(Math.max(0, gd.getAsNumber() - 1));
        if (scene._shield) { scene._shield = 0; scene._inv = 1.5; toast("Perisai menahan sengatan!"); sfx("gate_sound", 90); }
        dead = false;
      } else {
        scene._pdead = true;
        F.lives = Math.max(0, F.lives - 1);
        if (F.lives <= 0) scene._go = true;
        save();
      }
    }
    // --- Nyawa habis: Game Over (sebelum level diulang otomatis pada 1,6 detik)
    if (dead && scene._go && !scene._goSent && V("deathTime") >= 1.1) {
      scene._goSent = true;
      try { scene.requestChange(gdjs.SceneChangeCommand.CLEAR_SCENES, "GameOver"); } catch (e) { game.getSceneStack().replace("GameOver", true); }
    }

    // --- Level selesai: bit, XP, bonus naik level
    if (fin && !scene._rew) {
      scene._rew = true;
      const c = V("coins");
      const before = plv();
      F.bit += c + 10;
      F.xp += 2 * c + 50;
      if (plv() > before) F.bit += 5;
      for (const k in keyOf) delete F.got["L" + LV + keyOf[k]];
      save();
    }

    // --- Cerita awal level (tampil 7 detik)
    const cer = scene.getObjects("TxtCerita")[0];
    if (cer) {
      scene._cT = (scene._cT || 0) + dtm;
      if (scene._cT < 7) {
        if (!scene._cSet) { scene._cSet = true; cer.setText("Level 1: Gerbang Penjaga Data\nMesin Memori korsleting dan datanya hilang!\nNyalakan saklar S agar gerbang penjaga terbuka."); try { cer.setTextAlignment("center"); } catch (e) {} }
        cer.setX(game.getGameResolutionWidth() / 2 - cer.getWidth() / 2);
        if (cer.setOpacity) cer.setOpacity(255 * Math.min(1, Math.max(0, (7 - scene._cT) / 1.5)));
      } else if (!scene._cOff) { scene._cOff = true; if (cer.setOpacity) cer.setOpacity(0); }
    }

    // --- HUD atribut
    const hud = scene.getObjects("HudAtribut")[0];
    if (hud) {
      let l2 = "Kapasitor " + F.kap + " [Q Turbo]    Resistor " + F.res + " [E Perisai]";
      if (scene._turbo > 0) l2 += "    TURBO " + Math.ceil(scene._turbo) + "d";
      if (scene._shield) l2 += "    PERISAI";
      const txt = "Nyawa " + F.lives + "/5    Energi " + Math.floor(F.energy) + "/" + maxE() + "    Bit " + (F.bit + (fin ? 0 : V("coins"))) + "    XP " + F.xp + " (Lv " + plv() + ")\n" + l2 + (scene._msgT > 0 ? "\n" + scene._msg : "");
      if (hud.setText) hud.setText(txt); else if (hud.setString) hud.setString(txt);
    }
  }
} catch (e) {
  console.error("FlipFlop Circuit Quest - atribut error:", e);
}

// Tampilan HUD, animasi Sheren, dan suara lompat (JavaScript Event).
// Dibungkus try/catch supaya game tidak berhenti jika ada API yang berbeda di versi GDevelop Anda.
try {
  const scene = runtimeScene;
  const NEED = 3;
  const V = (n) => scene.getVariables().get(n).getAsNumber();
  const G = (n) => scene.getGame().getVariables().get(n).getAsNumber();
  const setText = (name, str, size, color) => {
    const o = scene.getObjects(name)[0];
    if (!o) return;
    if (o.setText) o.setText(str); else if (o.setString) o.setString(str);
    if (color && o.setColor) o.setColor(color);
    if (size && o.setCharacterSize) o.setCharacterSize(size);
  };
  const dead = V("dead") === 1;
  const won = V("won") === 1;
  const DEBUG = false;   // ubah ke false setelah lompat dipastikan normal
  let debugInfo = "";
  const player = scene.getObjects("Player")[0];
  if (player) {
    const b = player.getBehavior("PlatformerObject");
    const input = scene.getGame().getInputManager();
    const left = input.isKeyPressed(37) || input.isKeyPressed(65);
    const right = input.isKeyPressed(39) || input.isKeyPressed(68);
    const jumpKey = input.isKeyPressed(32) || input.isKeyPressed(38) || input.isKeyPressed(87);
    if (!dead && !won) {
      // Kontrol eksplisit (selain kontrol bawaan behavior): Spasi / Panah atas / W = lompat, A/D juga bisa gerak.
      if (jumpKey && b.simulateJumpKey) b.simulateJumpKey();
      if (left && b.simulateLeftKey) b.simulateLeftKey();
      if (right && b.simulateRightKey) b.simulateRightKey();
      if (left && !right && player.flipX) player.flipX(true);
      else if (right && !left && player.flipX) player.flipX(false);
    }
    let anim = "Idle";
    if (dead) anim = "Death";
    else if (!won) {
      if (!b.isOnFloor()) anim = "Jump";
      else if (b.isMoving()) anim = "Run";
    }
    player.setAnimationName(anim);
    const play = (n, vol) => scene.getGame().getSoundManager().playSound(n, false, vol === undefined ? 100 : vol, 1);
    // Langkah kaki: tiap 0,28 detik saat animasi Run.
    if (anim === "Run") {
      const now = Date.now();
      if (now - (player._lastStep || 0) > 280) { player._lastStep = now; play("step_sound", 55); }
    }
    // Mendarat: dari udara kembali ke lantai.
    const air = !b.isOnFloor();
    if (player._wasAir && !air && !dead && !won) play("land_sound", 80);
    player._wasAir = air;
    const jumping = !dead && !won && b.isJumping();
    if (jumping && !player._wasJumping) {
      scene.getGame().getSoundManager().playSound("jump_sound", false, 100, 1);
    }
    player._wasJumping = jumping;
    debugInfo = "  [debug lantai=" + (b.isOnFloor() ? "ya" : "tidak") + " tombol-lompat=" + (jumpKey ? "ya" : "tidak") + " melompat=" + (b.isJumping() ? "ya" : "tidak") + "]";
  }
  // Petir clock: siklus 2,5 detik -> 0-1,0 ON | 1,0-2,1 OFF | 2,1-2,5 PERINGATAN (kedip).
  const tc = (Date.now() / 1000) % 2.5;
  const petirOn = tc < 1.0;
  scene.getVariables().get("petirOn").setNumber(petirOn ? 1 : 0);
  if (scene._prevPetir === false && petirOn) {   // petir baru menyala: volume mengikuti jarak ke Sheren
    const pl = scene.getObjects("Player")[0];
    let vmax = 0;
    for (const p of scene.getObjects("ClockPetir")) {
      const dist = pl ? Math.abs(p.getX() - pl.getX()) : 999;
      vmax = Math.max(vmax, 100 - dist / 5);
    }
    if (vmax > 10) scene.getGame().getSoundManager().playSound("petir_sound", false, Math.min(100, vmax), 1);
  }
  scene._prevPetir = petirOn;
  for (const p of scene.getObjects("ClockPetir")) p.setAnimationName(petirOn ? "On" : (tc > 2.1 ? "Warn" : "Off"));
  // Bola listrik bergerak horizontal (sinus) di sekitar posisi awalnya.
  for (const o of scene.getObjects("BolaListrik")) {
    if (o._x0 === undefined) o._x0 = o.getX();
    o.setX(o._x0 + 45 * Math.sin((Date.now() / 1000) * 1.8));
  }
  const saklar = scene.getObjects("Saklar")[0];
  if (saklar) saklar.setAnimationName(V("sw") === 1 ? "On" : "Off");
  // Musik latar (channel 0). Hanya diganti jika lagunya berbeda, jadi tidak mengulang saat level di-restart.
  const sm = scene.getGame().getSoundManager();
  const track = "bgm_level1";
  const gTrack = scene.getGame().getVariables().get("musicTrack");
  if (gTrack.getAsString() !== track) {
    if (sm.playMusicOnChannel) sm.playMusicOnChannel(track, 0, true, 45, 1); else sm.playMusic(track, true, 45, 1);
    gTrack.setString(track);
  }
  // Tombol M = bisukan / nyalakan suara.
  const mDown = scene.getGame().getInputManager().isKeyPressed(77);
  if (mDown && !scene._mWas) {
    const gMute = scene.getGame().getVariables().get("muted");
    const m = gMute.getAsNumber() === 1 ? 0 : 1;
    gMute.setNumber(m);
    sm.setGlobalVolume(m ? 0 : 100);
  }
  scene._mWas = mDown;
  // Efek suara dipicu saat variabel berubah (lebih andal daripada aksi PlaySound di event).
  const cur = { coins: V("coins"), dead: V("dead"), sw: V("sw"), fin: V("finished") };
  if (!scene._prevSfx) { scene._prevSfx = Object.assign({}, cur); sm.playSound("start_sound", false, 60, 1); }   // bunyi awal level
  const P = scene._prevSfx;
  const sfx = (n) => sm.playSound(n, false, 100, 1);
  if (cur.coins > P.coins) sfx("coin_sound");                   // ambil koin
  if (cur.dead === 1 && P.dead === 0) {                          // mati: jatuh ke jurang atau kena listrik
    const pl = scene.getObjects("Player")[0];
    if (pl && pl.getY() > 600) sfx("fall_sound"); else sfx("hit_sound");
  }
  if (cur.sw === 1 && P.sw === 0) { sfx("switch_sound"); setTimeout(() => sfx("gate_sound"), 180); }   // saklar + gerbang terbuka
  if (cur.fin === 1 && P.fin === 0) sfx("win_sound");           // masuk chip FF
  scene._prevSfx = cur;
  const goal = scene.getObjects("Goal")[0];
  if (goal) goal.setAnimationName(V("coins") >= NEED ? "Open" : "Locked");

  setText("Judul", "Flip-Flop Circuit Quest - Sheren Edition  |  Level 1: SR Latch", 22, "255;255;255");
  setText("Skor", "Bit '1': " + V("coins") + " / " + NEED + "     Percobaan: " + (G("deaths") + 1) + (DEBUG ? debugInfo : ""), 18, "255;224;60");
  setText("Materi", "SR Latch (gerbang NOR): S=1,R=0 -> Q=1 (SET)    S=0,R=1 -> Q=0 (RESET)\nS=0,R=0 -> Q tetap (HOLD = menyimpan 1 bit)    S=1,R=1 -> terlarang!\nMisi: kumpulkan 3 bit '1' + sentuh saklar S (S=1) untuk membuka gerbang, lalu masuk ke chip FF.\nKontrol: Panah kiri/kanan = gerak, Spasi/Atas = lompat, R = ulang level.", 16, "130;230;255");
  let msg = "";
  if (dead) msg = "KORSLETING!  Mengulang level...";
  else if (won) msg = "SELAMAT! Semua level selesai.\nTekan ENTER atau SPASI untuk main lagi.";
  else if (V("hint") === 1) msg = "Kumpulkan " + NEED + " bit '1' dulu!";
  setText("Pesan", msg, 28, "255;255;255");
} catch (e) {
  console.error("FlipFlop Circuit Quest - JS event error:", e);
}

// ===== MENU HOOK (akhir): simpan progres & rekor waktu saat level selesai =====
try {
  const scene = runtimeScene;
  const game = scene.getGame();
  const F = game._ffcq;
  if (F && scene.getVariables().get("finished").getAsNumber() === 1 && !scene._saved) {
    scene._saved = true;
    const t = Math.round((scene._lt || 0) * 10) / 10;
    if (!(F.best[1] > 0) || t < F.best[1]) F.best[1] = t;
    F.done[1] = true;
    try { window.localStorage.setItem("ffcq_sheren_v1", JSON.stringify(F)); } catch (e) {}
  }
} catch (e) {
  console.error("FlipFlop Circuit Quest - menu hook error:", e);
}

// ===== MENU HOOK (awal): pengaturan suara, tombol ESC / P = menu jeda, penghitung waktu level =====
try {
const scene = runtimeScene;
const game = scene.getGame();
const sm = game.getSoundManager();
const input = game.getInputManager();
const KEY = "ffcq_sheren_v1";
if (!game._ffcq) {
  const def = { vol: 80, music: 1, sfx: 1, unlockAll: 0, done: {}, best: {}, quiz: -1, from: "menu" };
  let st = def;
  try { const raw = window.localStorage.getItem(KEY); if (raw) st = Object.assign({}, def, JSON.parse(raw)); } catch (e) { st = def; }
  if (!st.done || typeof st.done !== "object") st.done = {};
  if (!st.best || typeof st.best !== "object") st.best = {};
  st.from = "menu";
  game._ffcq = st;
}
const gv = (n) => game.getVariables().get(n);
if (!sm._ffcqPatched) {
  sm._ffcqPatched = true;
  const oPlay = sm.playSound.bind(sm);
  sm.playSound = function (n, l, v, p) { if (!game._ffcq.sfx) return undefined; return oPlay(n, l, v, p); };
  const oVol = sm.setGlobalVolume.bind(sm);
  sm.setGlobalVolume = function (v) { return oVol(Math.max(0, Math.min(100, v * game._ffcq.vol / 100))); };
  if (sm.playMusicOnChannel) {
    const oM = sm.playMusicOnChannel.bind(sm);
    sm.playMusicOnChannel = function (n, c, l, v, p) { if (!game._ffcq.music) return undefined; return oM(n, c, l, v, p); };
  }
  if (sm.playMusic) {
    const oM2 = sm.playMusic.bind(sm);
    sm.playMusic = function (n, l, v, p) { if (!game._ffcq.music) return undefined; return oM2(n, l, v, p); };
  }
  sm.setGlobalVolume(gv("muted").getAsNumber() === 1 ? 0 : 100);
}
gv("curLevel").setString("Level2");
const nowMs = Date.now();
const dt = Math.min(0.1, (nowMs - (scene._lt0 || nowMs)) / 1000);
scene._lt0 = nowMs;
scene._lt = (scene._lt || 0) + dt;   // detik bermain (tidak bertambah saat dijeda)
const down = input.isKeyPressed(27) || input.isKeyPressed(80);
if (scene._escWas === undefined) scene._escWas = down;   // tombol yang masih ditahan saat level mulai tidak dihitung
if (down && !scene._escWas) {
  scene._escWas = true;
  try { sm.playSound("klik_sound", false, 70, 1); } catch (e) {}
  try { scene.requestChange(gdjs.SceneChangeCommand.PUSH_SCENE, "Jeda"); } catch (e) { game.getSceneStack().push("Jeda"); }
} else scene._escWas = down;
} catch (e) {
  console.error("FlipFlop Circuit Quest - menu hook error:", e);
}

// ===== ATRIBUT, ITEM & BOOSTER (JavaScript Event): nyawa, energi, bit, XP, kapasitor, resistor, LED, Game Over =====
try {
  const scene = runtimeScene;
  const game = scene.getGame();
  const input = game.getInputManager();
  const sm = game.getSoundManager();
  const F = game._ffcq;
  const LV = 2;
  if (F) {
    const DEFA = { bit: 0, xp: 0, lives: 3, energy: 100, kap: 0, res: 0, got: {}, run: false, lastLevel: "Level1", lastQuiz: -1, tokoFrom: "menu" };
    for (const k in DEFA) if (F[k] === undefined) F[k] = DEFA[k];
    const save = () => { try { window.localStorage.setItem("ffcq_sheren_v1", JSON.stringify(F)); } catch (e) {} };
    const V = (n) => scene.getVariables().get(n).getAsNumber();
    const SV = (n, v) => scene.getVariables().get(n).setNumber(v);
    const plv = () => Math.min(5, 1 + Math.floor(F.xp / 100));
    const maxE = () => 100 + 10 * (plv() - 1);
    const sfx = (n, v) => { try { sm.playSound(n, false, v === undefined ? 100 : v, 1); } catch (e) {} };
    const now = Date.now();
    const dtm = Math.min(0.1, (now - (scene._at0 || now)) / 1000);
    scene._at0 = now;
    const toast = (s) => { scene._msg = s; scene._msgT = 2.5; };
    const player = scene.getObjects("Player")[0];
    const b = player ? player.getBehavior("PlatformerObject") : null;
    const keyOf = { ItemKap: "k", ItemRes: "r", ItemLed: "l" };

    // --- Awal level (sekali)
    if (!scene._atInit) {
      scene._atInit = true;
      if (!F.run) { F.run = true; F.lives = 3; F.energy = maxE(); F.got = {}; }
      F.lastLevel = "Level" + LV;
      for (const nm in keyOf) for (const o of scene.getObjects(nm).slice()) if (F.got["L" + LV + keyOf[nm]]) o.deleteFromScene(scene);
      scene._turbo = 0; scene._shield = 0; scene._inv = 0; scene._qw = false; scene._ew = false; scene._pdead = false; scene._go = false; scene._goSent = false; scene._rew = false;
      scene._msg = ""; scene._msgT = 0;
      save();
    }
    scene._msgT = Math.max(0, (scene._msgT || 0) - dtm);
    if (scene._inv > 0) scene._inv -= dtm;
    let dead = V("dead") === 1;
    const fin = V("finished") === 1;

    // --- Mengambil item
    if (player && !dead && !fin) {
      const px = player.getX(), py = player.getY(), pw = player.getWidth(), ph = player.getHeight();
      const hit = (o) => px < o.getX() + o.getWidth() && px + pw > o.getX() && py < o.getY() + o.getHeight() && py + ph > o.getY();
      for (const o of scene.getObjects("ItemKap").slice()) if (hit(o)) { o.deleteFromScene(scene); F.kap++; F.energy = Math.min(maxE(), F.energy + 30); F.got["L" + LV + "k"] = true; sfx("coin_sound"); toast("Kapasitor +1 (energi +30). Tekan Q = Turbo"); save(); }
      for (const o of scene.getObjects("ItemRes").slice()) if (hit(o)) { o.deleteFromScene(scene); F.res++; F.got["L" + LV + "r"] = true; sfx("coin_sound"); toast("Resistor +1. Tekan E = Perisai"); save(); }
      for (const o of scene.getObjects("ItemLed").slice()) if (hit(o)) {
        o.deleteFromScene(scene); F.got["L" + LV + "l"] = true;
        if (F.lives < 5) { F.lives++; toast("LED: nyawa +1"); } else { F.bit += 5; toast("LED: nyawa penuh, bit +5"); }
        sfx("benar_sound", 90); save();
      }
    }

    // --- Booster: Q = Turbo, E = Perisai
    const qd = input.isKeyPressed(81), ed = input.isKeyPressed(69);
    if (qd && !scene._qw && !dead && !fin) {
      if (scene._turbo > 0) toast("Turbo masih aktif");
      else if (F.kap < 1) toast("Tidak punya Kapasitor (beli di Toko, tekan T di menu)");
      else if (F.energy < 40) toast("Energi kurang (butuh 40)");
      else { F.kap--; F.energy -= 40; scene._turbo = 8; sfx("switch_sound"); toast("TURBO aktif 8 detik!"); save(); }
    }
    scene._qw = qd;
    if (ed && !scene._ew && !dead && !fin) {
      if (scene._shield) toast("Perisai sudah aktif");
      else if (F.res < 1) toast("Tidak punya Resistor (beli di Toko)");
      else { F.res--; scene._shield = 1; sfx("switch_sound"); toast("PERISAI aktif: menahan 1 sengatan listrik"); save(); }
    }
    scene._ew = ed;

    // --- Efek Turbo + energi pulih
    if (b) {
      const on = scene._turbo > 0;
      if (on !== scene._turboOn) { scene._turboOn = on; try { b.setJumpSpeed(on ? 693 : 620); b.setMaxSpeed(on ? 336 : 280); } catch (e) {} }
    }
    if (scene._turbo > 0) scene._turbo = Math.max(0, scene._turbo - dtm);
    else F.energy = Math.min(maxE(), F.energy + 5 * dtm);

    // --- Kematian baru: perisai menahan, atau nyawa berkurang (jurang tidak bisa ditahan)
    if (dead && !scene._pdead) {
      const pit = player ? player.getY() > 540 : false;
      if (!pit && (scene._inv > 0 || scene._shield)) {
        SV("dead", 0); SV("deathTime", 0);
        try { player.activateBehavior("PlatformerObject", true); } catch (e) {}
        const gd = game.getVariables().get("deaths");
        gd.setNumber(Math.max(0, gd.getAsNumber() - 1));
        if (scene._shield) { scene._shield = 0; scene._inv = 1.5; toast("Perisai menahan sengatan!"); sfx("gate_sound", 90); }
        dead = false;
      } else {
        scene._pdead = true;
        F.lives = Math.max(0, F.lives - 1);
        if (F.lives <= 0) scene._go = true;
        save();
      }
    }
    // --- Nyawa habis: Game Over (sebelum level diulang otomatis pada 1,6 detik)
    if (dead && scene._go && !scene._goSent && V("deathTime") >= 1.1) {
      scene._goSent = true;
      try { scene.requestChange(gdjs.SceneChangeCommand.CLEAR_SCENES, "GameOver"); } catch (e) { game.getSceneStack().replace("GameOver", true); }
    }

    // --- Level selesai: bit, XP, bonus naik level
    if (fin && !scene._rew) {
      scene._rew = true;
      const c = V("coins");
      const before = plv();
      F.bit += c + 10;
      F.xp += 2 * c + 50;
      if (plv() > before) F.bit += 5;
      for (const k in keyOf) delete F.got["L" + LV + keyOf[k]];
      save();
    }

    // --- Cerita awal level (tampil 7 detik)
    const cer = scene.getObjects("TxtCerita")[0];
    if (cer) {
      scene._cT = (scene._cT || 0) + dtm;
      if (scene._cT < 7) {
        if (!scene._cSet) { scene._cSet = true; cer.setText("Level 2: Ruang Sinkronisasi\nData hanya masuk saat clock berdenyut.\nAwas jurang dan petir di antara chip!"); try { cer.setTextAlignment("center"); } catch (e) {} }
        cer.setX(game.getGameResolutionWidth() / 2 - cer.getWidth() / 2);
        if (cer.setOpacity) cer.setOpacity(255 * Math.min(1, Math.max(0, (7 - scene._cT) / 1.5)));
      } else if (!scene._cOff) { scene._cOff = true; if (cer.setOpacity) cer.setOpacity(0); }
    }

    // --- HUD atribut
    const hud = scene.getObjects("HudAtribut")[0];
    if (hud) {
      let l2 = "Kapasitor " + F.kap + " [Q Turbo]    Resistor " + F.res + " [E Perisai]";
      if (scene._turbo > 0) l2 += "    TURBO " + Math.ceil(scene._turbo) + "d";
      if (scene._shield) l2 += "    PERISAI";
      const txt = "Nyawa " + F.lives + "/5    Energi " + Math.floor(F.energy) + "/" + maxE() + "    Bit " + (F.bit + (fin ? 0 : V("coins"))) + "    XP " + F.xp + " (Lv " + plv() + ")\n" + l2 + (scene._msgT > 0 ? "\n" + scene._msg : "");
      if (hud.setText) hud.setText(txt); else if (hud.setString) hud.setString(txt);
    }
  }
} catch (e) {
  console.error("FlipFlop Circuit Quest - atribut error:", e);
}

// Tampilan HUD, animasi Sheren, dan suara lompat (JavaScript Event).
// Dibungkus try/catch supaya game tidak berhenti jika ada API yang berbeda di versi GDevelop Anda.
try {
  const scene = runtimeScene;
  const NEED = 4;
  const V = (n) => scene.getVariables().get(n).getAsNumber();
  const G = (n) => scene.getGame().getVariables().get(n).getAsNumber();
  const setText = (name, str, size, color) => {
    const o = scene.getObjects(name)[0];
    if (!o) return;
    if (o.setText) o.setText(str); else if (o.setString) o.setString(str);
    if (color && o.setColor) o.setColor(color);
    if (size && o.setCharacterSize) o.setCharacterSize(size);
  };
  const dead = V("dead") === 1;
  const won = V("won") === 1;
  const DEBUG = false;   // ubah ke false setelah lompat dipastikan normal
  let debugInfo = "";
  const player = scene.getObjects("Player")[0];
  if (player) {
    const b = player.getBehavior("PlatformerObject");
    const input = scene.getGame().getInputManager();
    const left = input.isKeyPressed(37) || input.isKeyPressed(65);
    const right = input.isKeyPressed(39) || input.isKeyPressed(68);
    const jumpKey = input.isKeyPressed(32) || input.isKeyPressed(38) || input.isKeyPressed(87);
    if (!dead && !won) {
      // Kontrol eksplisit (selain kontrol bawaan behavior): Spasi / Panah atas / W = lompat, A/D juga bisa gerak.
      if (jumpKey && b.simulateJumpKey) b.simulateJumpKey();
      if (left && b.simulateLeftKey) b.simulateLeftKey();
      if (right && b.simulateRightKey) b.simulateRightKey();
      if (left && !right && player.flipX) player.flipX(true);
      else if (right && !left && player.flipX) player.flipX(false);
    }
    let anim = "Idle";
    if (dead) anim = "Death";
    else if (!won) {
      if (!b.isOnFloor()) anim = "Jump";
      else if (b.isMoving()) anim = "Run";
    }
    player.setAnimationName(anim);
    const play = (n, vol) => scene.getGame().getSoundManager().playSound(n, false, vol === undefined ? 100 : vol, 1);
    // Langkah kaki: tiap 0,28 detik saat animasi Run.
    if (anim === "Run") {
      const now = Date.now();
      if (now - (player._lastStep || 0) > 280) { player._lastStep = now; play("step_sound", 55); }
    }
    // Mendarat: dari udara kembali ke lantai.
    const air = !b.isOnFloor();
    if (player._wasAir && !air && !dead && !won) play("land_sound", 80);
    player._wasAir = air;
    const jumping = !dead && !won && b.isJumping();
    if (jumping && !player._wasJumping) {
      scene.getGame().getSoundManager().playSound("jump_sound", false, 100, 1);
    }
    player._wasJumping = jumping;
    debugInfo = "  [debug lantai=" + (b.isOnFloor() ? "ya" : "tidak") + " tombol-lompat=" + (jumpKey ? "ya" : "tidak") + " melompat=" + (b.isJumping() ? "ya" : "tidak") + "]";
  }
  // Petir clock: siklus 2,5 detik -> 0-1,0 ON | 1,0-2,1 OFF | 2,1-2,5 PERINGATAN (kedip).
  const tc = (Date.now() / 1000) % 2.5;
  const petirOn = tc < 1.0;
  scene.getVariables().get("petirOn").setNumber(petirOn ? 1 : 0);
  if (scene._prevPetir === false && petirOn) {   // petir baru menyala: volume mengikuti jarak ke Sheren
    const pl = scene.getObjects("Player")[0];
    let vmax = 0;
    for (const p of scene.getObjects("ClockPetir")) {
      const dist = pl ? Math.abs(p.getX() - pl.getX()) : 999;
      vmax = Math.max(vmax, 100 - dist / 5);
    }
    if (vmax > 10) scene.getGame().getSoundManager().playSound("petir_sound", false, Math.min(100, vmax), 1);
  }
  scene._prevPetir = petirOn;
  for (const p of scene.getObjects("ClockPetir")) p.setAnimationName(petirOn ? "On" : (tc > 2.1 ? "Warn" : "Off"));
  // Bola listrik bergerak horizontal (sinus) di sekitar posisi awalnya.
  for (const o of scene.getObjects("BolaListrik")) {
    if (o._x0 === undefined) o._x0 = o.getX();
    o.setX(o._x0 + 0 * Math.sin((Date.now() / 1000) * 1.8));
  }
  const saklar = scene.getObjects("Saklar")[0];
  if (saklar) saklar.setAnimationName(V("sw") === 1 ? "On" : "Off");
  // Musik latar (channel 0). Hanya diganti jika lagunya berbeda, jadi tidak mengulang saat level di-restart.
  const sm = scene.getGame().getSoundManager();
  const track = "bgm_level2";
  const gTrack = scene.getGame().getVariables().get("musicTrack");
  if (gTrack.getAsString() !== track) {
    if (sm.playMusicOnChannel) sm.playMusicOnChannel(track, 0, true, 45, 1); else sm.playMusic(track, true, 45, 1);
    gTrack.setString(track);
  }
  // Tombol M = bisukan / nyalakan suara.
  const mDown = scene.getGame().getInputManager().isKeyPressed(77);
  if (mDown && !scene._mWas) {
    const gMute = scene.getGame().getVariables().get("muted");
    const m = gMute.getAsNumber() === 1 ? 0 : 1;
    gMute.setNumber(m);
    sm.setGlobalVolume(m ? 0 : 100);
  }
  scene._mWas = mDown;
  // Efek suara dipicu saat variabel berubah (lebih andal daripada aksi PlaySound di event).
  const cur = { coins: V("coins"), dead: V("dead"), sw: V("sw"), fin: V("finished") };
  if (!scene._prevSfx) { scene._prevSfx = Object.assign({}, cur); sm.playSound("start_sound", false, 60, 1); }   // bunyi awal level
  const P = scene._prevSfx;
  const sfx = (n) => sm.playSound(n, false, 100, 1);
  if (cur.coins > P.coins) sfx("coin_sound");                   // ambil koin
  if (cur.dead === 1 && P.dead === 0) {                          // mati: jatuh ke jurang atau kena listrik
    const pl = scene.getObjects("Player")[0];
    if (pl && pl.getY() > 600) sfx("fall_sound"); else sfx("hit_sound");
  }
  if (cur.sw === 1 && P.sw === 0) { sfx("switch_sound"); setTimeout(() => sfx("gate_sound"), 180); }   // saklar + gerbang terbuka
  if (cur.fin === 1 && P.fin === 0) sfx("win_sound");           // masuk chip FF
  scene._prevSfx = cur;
  const goal = scene.getObjects("Goal")[0];
  if (goal) goal.setAnimationName(V("coins") >= NEED ? "Open" : "Locked");

  setText("Judul", "Flip-Flop Circuit Quest - Sheren Edition  |  Level 2: D Flip-Flop", 22, "255;255;255");
  setText("Skor", "Bit '1': " + V("coins") + " / " + NEED + "     Percobaan: " + (G("deaths") + 1) + (DEBUG ? debugInfo : ""), 18, "255;224;60");
  setText("Materi", "D Flip-Flop: pada tepi clock naik, Q mengambil nilai D.\nD=0 -> Q=0     D=1 -> Q=1     (di luar tepi clock, Q tidak berubah)\nMisi: kumpulkan 4 bit D + sentuh saklar S di batu kecil untuk membuka gerbang. Awas jurang & listrik!\nKontrol: Panah kiri/kanan = gerak, Spasi/Atas = lompat, R = ulang level.", 16, "130;230;255");
  let msg = "";
  if (dead) msg = "KORSLETING!  Mengulang level...";
  else if (won) msg = "SELAMAT! Semua level selesai.\nTekan ENTER atau SPASI untuk main lagi.";
  else if (V("hint") === 1) msg = "Kumpulkan " + NEED + " bit '1' dulu!";
  setText("Pesan", msg, 28, "255;255;255");
} catch (e) {
  console.error("FlipFlop Circuit Quest - JS event error:", e);
}

