}

// ===== MENU HOOK (awal): pengaturan suara, tombol ESC / P = kembali ke Menu Utama =====
try {
const scene = runtimeScene;
const game = scene.getGame();
const sm = game.getSoundManager();
const input = game.getInputManager();
const KEY = "ffcq_sheren_v1";
if (!game._ffcq) {
  const def = { vol: 80, music: 1, sfx: 1, unlockAll: 0, done: {}, best: {}, quiz: -1, from: "menu" };
  let st = def;
  try { const raw = window.localStorage.getItem(KEY); if (raw) st = Object.assign({}, def, JSON.parse(raw)); } catch (e) { st = def; }
  if (!st.done || typeof st.done !== "object") st.done = {};
  if (!st.best || typeof st.best !== "object") st.best = {};
  st.from = "menu";
  game._ffcq = st;
}
const gv = (n) => game.getVariables().get(n);
if (!sm._ffcqPatched) {
  sm._ffcqPatched = true;
  const oPlay = sm.playSound.bind(sm);
  sm.playSound = function (n, l, v, p) { if (!game._ffcq.sfx) return undefined; return oPlay(n, l, v, p); };
  const oVol = sm.setGlobalVolume.bind(sm);
  sm.setGlobalVolume = function (v) { return oVol(Math.max(0, Math.min(100, v * game._ffcq.vol / 100))); };
  if (sm.playMusicOnChannel) {
    const oM = sm.playMusicOnChannel.bind(sm);
    sm.playMusicOnChannel = function (n, c, l, v, p) { if (!game._ffcq.music) return undefined; return oM(n, c, l, v, p); };
  }
  if (sm.playMusic) {
    const oM2 = sm.playMusic.bind(sm);
    sm.playMusic = function (n, l, v, p) { if (!game._ffcq.music) return undefined; return oM2(n, l, v, p); };
  }
  sm.setGlobalVolume(gv("muted").getAsNumber() === 1 ? 0 : 100);
}
gv("curLevel").setString("Kuis");
const nowMs = Date.now();
const dt = Math.min(0.1, (nowMs - (scene._lt0 || nowMs)) / 1000);
scene._lt0 = nowMs;
scene._lt = (scene._lt || 0) + dt;   // detik bermain (tidak bertambah saat dijeda)
const down = input.isKeyPressed(27) || input.isKeyPressed(80);
if (scene._escWas === undefined) scene._escWas = down;   // tombol yang masih ditahan saat level mulai tidak dihitung
if (down && !scene._escWas) {
  scene._escWas = true;
  try { sm.playSound("klik_sound", false, 70, 1); } catch (e) {}
  try { scene.requestChange(gdjs.SceneChangeCommand.CLEAR_SCENES, "MenuUtama"); } catch (e) { game.getSceneStack().replace("MenuUtama", true); }
} else scene._escWas = down;
} catch (e) {
  console.error("FlipFlop Circuit Quest - menu hook error:", e);
}

// Logika kuis akhir (JavaScript Event). Jawab dengan tombol A/B/C/D (atau 1-4), ENTER/SPASI = lanjut.
try {
  const scene = runtimeScene;
  const input = scene.getGame().getInputManager();
  const sm = scene.getGame().getSoundManager();
  const QUIZ = [{"q": "Pada SR Latch, kondisi S=1 dan R=1 secara bersamaan disebut ...", "o": ["Set", "Reset", "Hold (menyimpan data)", "Terlarang (invalid)"], "a": 3, "e": "S=R=1 membuat Q dan Q' sama-sama 0 (pada latch NOR), sehingga keduanya tidak saling komplemen."}, {"q": "Pada D Flip-Flop, output Q mengambil nilai input D ketika ...", "o": ["clock berada pada tepi naik", "input D berubah", "rangkaian dimatikan", "tombol reset ditekan"], "a": 0, "e": "D Flip-Flop hanya meng-sampel D pada tepi clock; di luar itu Q tetap."}, {"q": "JK Flip-Flop dengan J=1 dan K=1 saat clock aktif akan ...", "o": ["Set Q = 1", "Reset Q = 0", "Toggle (Q menjadi kebalikannya)", "Hold (Q tetap)"], "a": 2, "e": "J=K=1 adalah mode toggle: Q berganti 0->1 atau 1->0 pada setiap clock."}, {"q": "Berapa bit data yang dapat disimpan oleh satu flip-flop?", "o": ["8 bit", "4 bit", "2 bit", "1 bit"], "a": 3, "e": "Satu flip-flop = elemen memori 1 bit; register 8 bit memakai 8 flip-flop."}, {"q": "Rangkaian yang outputnya bergantung pada input DAN keadaan sebelumnya disebut ...", "o": ["Kombinasional", "Sekuensial", "Analog", "Pasif"], "a": 1, "e": "Flip-flop termasuk rangkaian sekuensial karena memiliki memori (state)."}, {"q": "Jika Q=0, lalu JK Flip-Flop diberi J=1, K=0 dan clock aktif, Q berikutnya adalah ...", "o": ["0", "Tidak berubah", "1", "Tidak terdefinisi"], "a": 2, "e": "J=1, K=0 berarti Set, sehingga Q menjadi 1."}];
  const LETTERS = ["A", "B", "C", "D"];
  const setText = (name, str, size, color) => {
    const o = scene.getObjects(name)[0];
    if (!o) return;
    if (o.setText) o.setText(str); else if (o.setString) o.setString(str);
    if (color && o.setColor) o.setColor(color);
    if (size && o.setCharacterSize) o.setCharacterSize(size);
  };
  const keys = {
    a: [65, 49, 97], b: [66, 50, 98], c: [67, 51, 99], d: [68, 52, 100], next: [13, 32], mute: [77]
  };
  const isDown = (k) => keys[k].some((c) => input.isKeyPressed(c));
  if (!scene._quiz) {
    scene._quiz = { i: 0, score: 0, state: "ask", picked: -1, prev: {} };
    for (const k in keys) scene._quiz.prev[k] = isDown(k);   // tombol yang masih ditahan dari level tidak dihitung
  }
  const S = scene._quiz;
  const edge = (k) => { const d = isDown(k); const was = S.prev[k]; S.prev[k] = d; return d && !was; };
  const pressed = { a: edge("a"), b: edge("b"), c: edge("c"), d: edge("d") };
  const next = edge("next");
  if (edge("mute")) {
    const gMute = scene.getGame().getVariables().get("muted");
    const m = gMute.getAsNumber() === 1 ? 0 : 1; gMute.setNumber(m); sm.setGlobalVolume(m ? 0 : 100);
  }
  const N = QUIZ.length;
  const pose = scene.getObjects("SherenPose")[0];
  const q = QUIZ[Math.min(S.i, N - 1)];
  const questionText = () => "Soal " + (S.i + 1) + " dari " + N + "\n" + q.q + "\n\n" +
    q.o.map((t, k) => LETTERS[k] + ".  " + t).join("\n");

  if (S.state === "ask") {
    setText("Materi", questionText() + "\n\nTekan A / B / C / D (atau 1-4) untuk menjawab.", 22, "130;230;255");
    setText("Pesan", "", 22, "255;255;255");
    if (pose) pose.setAnimationName("Idle");
    const idx = pressed.a ? 0 : pressed.b ? 1 : pressed.c ? 2 : pressed.d ? 3 : -1;
    if (idx >= 0) {
      S.picked = idx;
      if (idx === q.a) { S.score++; sm.playSound("benar_sound", false, 100, 1); }
      else sm.playSound("salah_sound", false, 100, 1);
      S.state = "feedback";
    }
  } else if (S.state === "feedback") {
    const ok = S.picked === q.a;
    setText("Materi", questionText(), 22, "130;230;255");
    setText("Pesan", (ok ? "BENAR!  " : "SALAH.  Jawaban benar: " + LETTERS[q.a] + ".  ") + "\n" + q.e +
      "\n\nTekan ENTER atau SPASI untuk lanjut.", 22, ok ? "90;255;140" : "255;120;120");
    if (pose) pose.setAnimationName(ok ? "Senang" : "Sedih");
    if (next) {
      sm.playSound("klik_sound", false, 80, 1);
      S.i++;
      if (S.i >= N) { S.state = "result"; sm.playSound("win_sound", false, 100, 1); }
      else S.state = "ask";
    }
  } else {
    const nilai = Math.round((S.score / N) * 100);
    const komentar = S.score >= 5 ? "Luar biasa! Kamu menguasai dasar flip-flop."
      : S.score >= 3 ? "Bagus! Ulangi level untuk memperdalam materi."
      : "Semangat! Baca lagi materi di tiap level, lalu coba lagi.";
    setText("Materi", "KUIS SELESAI!\n\nSkor: " + S.score + " dari " + N + "      Nilai: " + nilai + "\n\n" + komentar, 26, "255;224;60");
