// ===== FLIP-FLOP CIRCUIT QUEST - MENU (JavaScript Event) =====
// Dibungkus try/catch supaya game tidak berhenti jika ada API yang berbeda di versi GDevelop Anda.
try {
const scene = runtimeScene;
const game = scene.getGame();
const sm = game.getSoundManager();
const input = game.getInputManager();
const KEY = "ffcq_sheren_v1";
// ---- Data tersimpan (pengaturan + progres). Memakai localStorage; jika tidak tersedia, tetap jalan tanpa menyimpan.
if (!game._ffcq) {
  const def = { vol: 80, music: 1, sfx: 1, unlockAll: 0, done: {}, best: {}, quiz: -1, from: "menu" };
  let st = def;
  try { const raw = window.localStorage.getItem(KEY); if (raw) st = Object.assign({}, def, JSON.parse(raw)); } catch (e) { st = def; }
  if (!st.done || typeof st.done !== "object") st.done = {};
  if (!st.best || typeof st.best !== "object") st.best = {};
  st.from = "menu";
  game._ffcq = st;
}
const F = game._ffcq;
const DEFA = { bit: 0, xp: 0, lives: 3, energy: 100, kap: 0, res: 0, got: {}, run: false, lastLevel: "Level1", lastQuiz: -1, tokoFrom: "menu" };
for (const k in DEFA) if (F[k] === undefined) F[k] = DEFA[k];
const plv = () => Math.min(5, 1 + Math.floor(F.xp / 100));
const maxE = () => 100 + 10 * (plv() - 1);
const saveState = () => { try { window.localStorage.setItem(KEY, JSON.stringify(F)); } catch (e) {} };
const gv = (n) => game.getVariables().get(n);
const applyVol = () => { try { sm.setGlobalVolume(gv("muted").getAsNumber() === 1 ? 0 : 100); } catch (e) {} };
// ---- Pengaturan suara: efek suara on/off, musik on/off, volume utama (membungkus fungsi SoundManager sekali saja).
if (!sm._ffcqPatched) {
  sm._ffcqPatched = true;
  const oPlay = sm.playSound.bind(sm);
  sm.playSound = function (n, l, v, p) { if (!game._ffcq.sfx) return undefined; return oPlay(n, l, v, p); };
  const oVol = sm.setGlobalVolume.bind(sm);
  sm.setGlobalVolume = function (v) { return oVol(Math.max(0, Math.min(100, v * game._ffcq.vol / 100))); };
  if (sm.playMusicOnChannel) {
    const oM = sm.playMusicOnChannel.bind(sm);
    sm.playMusicOnChannel = function (n, c, l, v, p) { if (!game._ffcq.music) return undefined; return oM(n, c, l, v, p); };
  }
  if (sm.playMusic) {
    const oM2 = sm.playMusic.bind(sm);
    sm.playMusic = function (n, l, v, p) { if (!game._ffcq.music) return undefined; return oM2(n, l, v, p); };
  }
  applyVol();
}
const sfx = (n, v) => { try { sm.playSound(n, false, v === undefined ? 100 : v, 1); } catch (e) {} };
const gTrack = gv("musicTrack");
const trackVol = (n) => (n === "bgm_menu" ? 55 : 45);
const playTrack = (n) => {
  try {
    if (F.music) { if (sm.playMusicOnChannel) sm.playMusicOnChannel(n, 0, true, trackVol(n), 1); else sm.playMusic(n, true, trackVol(n), 1); }
    gTrack.setString(n);
  } catch (e) {}
};
const stopMusic = () => { try { if (sm.stopMusicOnChannel) sm.stopMusicOnChannel(0); } catch (e) {} };
// ---- Pindah scene: "clear" = ganti scene (hapus tumpukan), "push" = tumpuk di atas (jeda), "pop" = kembali.
const nav = (cmd, name) => {
  try {
    const C = gdjs.SceneChangeCommand;
    if (cmd === "pop") scene.requestChange(C.POP_SCENE);
    else if (cmd === "push") scene.requestChange(C.PUSH_SCENE, name);
    else scene.requestChange(C.CLEAR_SCENES, name);
  } catch (e) {
    const stack = game.getSceneStack();
    if (cmd === "pop") stack.pop(); else if (cmd === "push") stack.push(name); else stack.replace(name, true);
  }
};

// ---- Input (keyboard + mouse/sentuh), waktu, efek fade.
const KEYS = { up: [38, 87], down: [40, 83], left: [37, 65], right: [39, 68], ok: [13, 32], esc: [27], p: [80], mute: [77], toko: [84], k1: [49, 97], k2: [50, 98], k3: [51, 99], k4: [52, 100] };
const isDown = (k) => KEYS[k].some((c) => input.isKeyPressed(c));
if (!scene._m) {
  const Wd = game.getGameResolutionWidth ? game.getGameResolutionWidth() : 960;
  scene._m = { T: 0, t: Date.now(), prev: {}, pm: input.isMouseButtonPressed(0), lmx: -1, lmy: -1, sel: 0, lastSel: undefined,
    W: Wd, dx: Math.round((Wd - 960) / 2), fade: 0, leave: null, init: false, hold: {}, msg: "", msgT: 0, conf: 0 };
  for (const k in KEYS) scene._m.prev[k] = isDown(k);   // tombol yang masih ditahan dari scene sebelumnya tidak dihitung
}
const S = scene._m;
const nowMs = Date.now();
const dt = Math.min(0.1, (nowMs - S.t) / 1000);
S.t = nowMs; S.T += dt;
const W = S.W;
const ob = (n) => scene.getObjects(n)[0];
const obs = (n) => scene.getObjects(n).slice();
const mx = input.getMouseX(), my = input.getMouseY();
const moved = (mx !== S.lmx || my !== S.lmy);
S.lmx = mx; S.lmy = my;
const md = input.isMouseButtonPressed(0);
const click = md && !S.pm;
S.pm = md;
const edge = (k) => { const d = isDown(k); const w = S.prev[k]; S.prev[k] = d; return d && !w; };
const rep = (k) => {   // tekan = 1x, tahan = berulang
  const d = isDown(k); const was = S.prev[k]; S.prev[k] = d;
  if (!d) { S.hold[k] = 0; return false; }
  if (!was) { S.hold[k] = S.T + 0.35; return true; }
  if (S.T >= S.hold[k]) { S.hold[k] = S.T + 0.06; return true; }
  return false;
};
const hitBtn = (o) => mx >= o.getX() + 10 && mx <= o.getX() + o.getWidth() - 10 && my >= o.getY() + 8 && my <= o.getY() + o.getHeight() - 9;
const go = (fn) => { if (!S.leave) S.leave = { t: 0, fn: fn, done: false }; };
const setTxt = (o, str, color, size) => {
  if (!o) return;
  if (o.setText) o.setText(str); else if (o.setString) o.setString(str);
  if (color && o.setColor) o.setColor(color);
  if (size && o.setCharacterSize) o.setCharacterSize(size);
};
const ctext = (o, str, cx, color, size) => { if (!o) return; setTxt(o, str, color, size); o.setX(cx - o.getWidth() / 2); };
const mmss = (s) => { const t = Math.max(0, Math.round(s)); return Math.floor(t / 60) + ":" + (t % 60 < 10 ? "0" : "") + (t % 60); };
if (edge("mute")) { const gm = gv("muted"); const m = gm.getAsNumber() === 1 ? 0 : 1; gm.setNumber(m); applyVol(); }
if (S.msgT > 0) { S.msgT -= dt; if (S.msgT <= 0) S.msg = ""; }
S.conf = Math.max(0, S.conf - dt);
const firstFrame = !S.init;
if (firstFrame) {
  for (const n of ["MenuBg", "JudulSelesai", "PanelToko", "SherenPose", "BtnMenu"]) for (const o of obs(n)) o.setX(o.getX() + S.dx);
  const bg = ob("MenuBg"); if (bg && W > 1600) { bg.setX(0); bg.setWidth(W); }
  const tr = ob("Tirai"); if (tr) { tr.setWidth(W + 40); tr.setHeight(720); tr.setPosition(-20, -20); }
}
const hintO = ob("TxtHint"), footO = ob("TxtFooter");
// Daftar tombol vertikal: pilih dengan panah atas/bawah (atau W/S) + ENTER, atau arahkan & klik mouse.
const listNav = (items) => {
  let hov = -1;
  items.forEach((it, i) => { if (it.o && hitBtn(it.o)) hov = i; });
  if (moved && hov >= 0) S.sel = hov;
  const n = items.length;
  if (edge("up")) S.sel = (S.sel + n - 1) % n;
  if (edge("down")) S.sel = (S.sel + 1) % n;
  if (S.sel !== S.lastSel) { if (S.lastSel !== undefined) sfx("klik_sound", 40); S.lastSel = S.sel; }
  let act = -1;
  if (click && hov >= 0) { S.sel = hov; act = hov; }
  else if (edge("ok")) act = S.sel;
  items.forEach((it, i) => { if (it.o) it.o.setAnimationName((it.n || "n") === "n" ? (i === S.sel ? "h" : "n") : (i === S.sel ? it.n + "h" : it.n)); });
  return act;
};



